import { ImageResponse } from 'next/og';
import { SITE_NAME } from '@/lib/seo';

/** Shared 1200×630 Open Graph dimensions + content type for every `opengraph-image` route. */
export const OG_SIZE = { width: 1200, height: 630 } as const;
export const OG_CONTENT_TYPE = 'image/png';

/** `public/advance-labs-mark-256.png` as a data URI; Satori can't fetch relative assets. */
const MARK_DATA_URI = 'data:image/png;base64,';

/** Copy for one social/AI share card. `eyebrow` is the tool tag, `title` the headline. */
export interface OgCard {
  eyebrow: string;
  title: string;
  subtitle: string;
}

/**
 * Branded Open Graph card renderer shared by the root and every tool route. Ink ground, a faint
 * violet/signal wash, the Advance Labs sphere and wordmark, an eyebrow tag, a large headline, and
 * a subtitle. Every multi-child element sets `display: 'flex'` explicitly (a Satori requirement
 * under `next/og`). Keeping this in one place means all cards stay visually consistent.
 */
export function renderOgImage({ eyebrow, title, subtitle }: OgCard): ImageResponse {
  return new ImageResponse(
    (
      <div
        style={{
          width: '100%',
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'space-between',
          padding: '72px',
          backgroundColor: '#0a0a0b',
          backgroundImage:
            'radial-gradient(900px 520px at 12% -8%, rgba(124,58,237,0.35), transparent 60%), radial-gradient(820px 520px at 100% 110%, rgba(168,243,38,0.16), transparent 55%), radial-gradient(700px 480px at 70% 0%, rgba(182,164,253,0.22), transparent 60%)',
          fontFamily: 'sans-serif',
        }}
      >
        {/* Top row: brand lockup + tool eyebrow */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '24px' }}>
          {/* The Advance Labs sphere, inlined so the edge runtime needs no asset fetch. */}
          <img
            src={MARK_DATA_URI}
            width={92}
            height={92}
            alt=""
            style={{ width: '92px', height: '92px', objectFit: 'contain' }}
          />
          <div style={{ display: 'flex', fontSize: '40px', fontWeight: 700, letterSpacing: '-0.02em' }}>
            <span style={{ color: '#A8F326' }}>AEO&nbsp;Toolkit</span>
          </div>
          <div
            style={{
              display: 'flex',
              marginLeft: 'auto',
              alignItems: 'center',
              padding: '10px 22px',
              borderRadius: '999px',
              border: '1px solid rgba(255,255,255,0.14)',
              backgroundColor: 'rgba(255,255,255,0.05)',
              color: '#A8F326',
              fontSize: '24px',
              fontWeight: 600,
              letterSpacing: '0.04em',
              textTransform: 'uppercase',
            }}
          >
            {eyebrow}
          </div>
        </div>

        {/* Headline block */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '22px' }}>
          <div
            style={{
              display: 'flex',
              color: '#fff',
              fontSize: '72px',
              fontWeight: 700,
              lineHeight: 1.05,
              letterSpacing: '-0.03em',
              maxWidth: '1010px',
            }}
          >
            {title}
          </div>
          <div style={{ display: 'flex', color: '#9aa3b8', fontSize: '30px', maxWidth: '940px' }}>
            {subtitle}
          </div>
        </div>

        {/* Footer accent bar */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
          <div
            style={{
              display: 'flex',
              width: '220px',
              height: '8px',
              borderRadius: '999px',
              backgroundImage: 'linear-gradient(90deg, #7C3AED 0%, #B6A4FD 50%, #A8F326 100%)',
            }}
          />
          <div style={{ display: 'flex', color: '#6b7390', fontSize: '26px' }}>{SITE_NAME}</div>
        </div>
      </div>
    ),
    { ...OG_SIZE },
  );
}
